"""K1-FA4 v7 lab (box only): v7 (v6 + K1-FA4 v4's FP8-PV core, kernels/muse_attention_decode/k1_fa4v7.py generated by
tools/gen_k1_fa4v7.py) vs the shipped v6, same process, judge inputs (problem generate_input), graph replay, cold L2 (1 GB
READ sweep before every replay), variants replayed interleaved (paired). Stages (comma list, --stages):
  selftest  v6 and v7 k1fa4_self_test (stock-relative rule vs the r1 stock path, cache bytes == r1)
  fn        full kernel_fn v6 vs v7 on --shapes, with the problem's check_implementation message for each
  core      FA4 core only (k1fa4_fwd_partials; prologue run once outside the graph) v6 vs v7 on --core-shapes
  mask      exp2 timing mask on --mask-shapes: v7 core with the F16-PV / FP8-PV kernel x MUFU / FFMA-only exp
  emu       partial software exp2 variants (mode 2) vs mode 0 on --mask-shapes, then error checks of the best one;
            with --emu auto it runs only if the mask stage saved >= 15% of the FP8-PV core
  python3 kernels/muse_attention_decode/k1_fa4v7_lab.py --stages selftest,fn,core,mask,emu
"""
import argparse
import json
import statistics
import sys
import time
import traceback
from pathlib import Path

import torch

HERE = Path(__file__).resolve().parent
PROB = HERE.parents[1] / "problems" / "muse_attention_decode"
sys.path.insert(0, str(HERE))
sys.path.insert(0, str(PROB))
import reference  # noqa: E402

ap = argparse.ArgumentParser()
ap.add_argument("--stages", default="selftest,fn,core,mask,emu")
ap.add_argument("--shapes", default="11,9,10,8,6,7,0,2,4,1")
ap.add_argument("--core-shapes", default="11,9,10,8")
ap.add_argument("--mask-shapes", default="11,9")
ap.add_argument("--reps", type=int, default=40)
ap.add_argument("--emu", default="auto")  # auto | on | off
ap.add_argument("--emu-variants", default="8:1:3,4:1:3,16:3:3,8:1:2")  # freq:res:deg
ap.add_argument("--pv8-sliding", type=int, default=1)
ap.add_argument("--err-shapes", default="11,9,10,8")
ap.add_argument("--p8-offset", type=float, default=None)
args = ap.parse_args()
stages = set(args.stages.split(","))

t0 = time.time()
import k1_fa4v6 as V6  # noqa: E402
import k1_fa4v7 as V7  # noqa: E402

print(f"[lab7] import v6 + v7 {time.time() - t0:.1f}s; v7 PV8 {V7.K1FA4_PV8} REGS1 {V7.K1FA4_REGS1}", flush=True)
if not args.pv8_sliding:
    V7.K1FA4_PV8[("sliding", 1)] = V7.K1FA4_PV8[("sliding", 8)] = False
dev = torch.device("cuda")
benches = json.loads((PROB / "meta.json").read_text())["benchmarks"]
flush_buf = torch.ones(256 * 1024 * 1024, dtype=torch.float32, device=dev)  # 1 GB, read sweep
sink = torch.empty((), dtype=torch.float32, device=dev)


def say(*a):
    print(*a, flush=True)


def time_interleaved(graphs, reps):
    """graphs: list of CUDAGraphs; replayed round-robin, each after a cold-L2 read sweep; returns medians in us."""
    ts = [[] for _ in graphs]
    for _ in range(reps):
        for j, g in enumerate(graphs):
            torch.sum(flush_buf, dim=0, out=sink)
            a, b = torch.cuda.Event(enable_timing=True), torch.cuda.Event(enable_timing=True)
            a.record()
            g.replay()
            b.record()
            b.synchronize()
            ts[j].append(a.elapsed_time(b) * 1000.0)
    return [statistics.median(t) for t in ts]


def capture(fn):
    for _ in range(2):
        fn()
    torch.cuda.synchronize()
    g = torch.cuda.CUDAGraph()
    with torch.cuda.graph(g):
        fn()
    torch.cuda.synchronize()
    return g


eg = torch.cuda.CUDAGraph()
with torch.cuda.graph(eg):
    pass
FLOOR = time_interleaved([eg], 50)[0]
say(f"[lab7] empty-graph floor {FLOOR:.2f} us")


def bench_kw(i):
    return {k: v for k, v in benches[i].items() if k not in ("load", "weight")}


def label(i):
    bm = benches[i]
    return f"[{i:2d}] {bm['load']} {bm['layer']} B{bm['batch']}"


def check(fn, i):
    data = reference.generate_input(**bench_kw(i))
    out = fn(data)
    torch.cuda.synchronize()
    ok, msg = reference.check_implementation(data, reference.collect(data, out))
    del data, out
    torch.cuda.empty_cache()
    return ok, msg


def core_closure(M, data):
    """M.k1fa4_fwd_partials alone on data (prologue run once, eagerly, to produce q8 and the new cache rows)."""
    cfg = data["config"]
    batch, length = cfg["batch"], cfg["q_len"]
    hq, hkv, d = cfg["num_q_heads"], cfg["num_kv_heads"], cfg["head_dim"]
    tokens = batch * length
    qkv = data["qkv"].view(tokens, -1)
    q8 = torch.empty((tokens, hq * d), dtype=torch.float8_e4m3fn, device=dev)
    n_rows = tokens * (hq + 2 * hkv)
    block_m = 4 if n_rows < 1024 else (8 if n_rows < 8192 else 16)
    theta = cfg["rope_theta"]
    cos_sin = M.k1fa4_cos_sin(theta, d, dev) if theta else qkv
    M._k1fa4_prologue[(M.triton.cdiv(n_rows, block_m),)](
        qkv, q8, data["positions"] if theta else qkv, cos_sin, data["k_cache"].view(-1, hkv * d),
        data["v_cache"].view(-1, hkv * d), data["cache_loc"], M.K1FA4_RMS_EPS, qkv.stride(0), n_rows, hq, hkv, d,
        M.triton.next_power_of_2(d), block_m, HAS_ROPE=bool(theta), USE_PDL=False, num_warps=4)
    window = cfg["window"]
    max_k = data["page_table"].shape[1]
    keys = min(max_k, window + length) if window else max_k
    ns = M.K1FA4_SPLITS.get(("sliding" if window else "full", batch)) or M.k1fa4_num_splits_for(batch, hkv, keys)
    M.k1fa4_K["pdl"] = True
    scale = cfg["sm_scale"] * cfg["qk_scale_factor"]
    q8v = q8.view(batch, length, hq, d)

    def fn():
        return M.k1fa4_fwd_partials(q8v, data["k_cache"], data["v_cache"], data["page_table"], data["cache_seqlens"],
                                    scale, ns, window=window)
    return fn, ns


def run_stage(name, f):
    if name not in stages:
        return None
    t0 = time.time()
    try:
        r = f()
    except Exception as ex:  # noqa: BLE001
        say(f"[lab7] stage {name} ERROR {type(ex).__name__}: {str(ex)[:300]}")
        say("\n".join("TB| " + ln for ln in traceback.format_exc()[-3000:].splitlines()))
        r = None
    say(f"[lab7] stage {name} done in {time.time() - t0:.1f}s")
    return r


def st_selftest():
    ok6 = V6.k1fa4_self_test(dev)
    say(f"[lab7] v6 self-test {'PASS' if ok6 else 'FAIL'}")
    ok7 = V7.k1fa4_self_test(dev)
    say(f"[lab7] v7 self-test {'PASS' if ok7 else 'FAIL'} (PV8 {V7.K1FA4_PV8})")
    return ok7


def st_fn():
    for i in [int(x) for x in args.shapes.split(",")]:
        msgs = []
        for nm, M in (("v6", V6), ("v7", V7)):
            ok, msg = check(lambda d, M=M: M.k1fa4_run(d), i)
            msgs.append(f"{nm} {'PASS' if ok else 'FAIL'} {msg[:90]}")
        data = reference.generate_input(**bench_kw(i))
        g6 = capture(lambda: V6.k1fa4_run(data))
        g7 = capture(lambda: V7.k1fa4_run(data))
        t6, t7, t6b, t7b = time_interleaved([g6, g7, g6, g7], args.reps)
        t6, t7, t6b, t7b = (t - FLOOR for t in (t6, t7, t6b, t7b))
        say(f"FN {label(i)} | v6 {t6:7.2f} / {t6b:7.2f} | v7 {t7:7.2f} / {t7b:7.2f} | d {t7 - t6:+6.2f} / "
            f"{t7b - t6b:+6.2f} us ({100 * ((t7 + t7b) / (t6 + t6b) - 1):+.1f}%)")
        for m in msgs:
            say(f"   {m}")
        del g6, g7, data
        torch.cuda.empty_cache()


def st_core():
    for i in [int(x) for x in args.core_shapes.split(",")]:
        data = reference.generate_input(**bench_kw(i))
        f6, ns = core_closure(V6, data)
        f7, _ = core_closure(V7, data)
        g6, g7 = capture(f6), capture(f7)
        t = [x - FLOOR for x in time_interleaved([g6, g7, g6, g7], args.reps)]
        say(f"CORE {label(i)} splits {ns} | v6 {t[0]:7.2f} / {t[2]:7.2f} | v7 {t[1]:7.2f} / {t[3]:7.2f} | "
            f"({100 * ((t[1] + t[3]) / (t[0] + t[2]) - 1):+.1f}%)")
        del g6, g7, data
        torch.cuda.empty_cache()


MASK = {}


def set_core(pv8, mode, freq=8, res=1, deg=3):
    V7.K1FA4_PV8[("full", 8)] = pv8
    V7.K1FA4_PV8[("sliding", 8)] = pv8 if args.pv8_sliding else False
    V7.K1FA4_EX2.update(mode=mode, freq=freq, res=res, deg=deg)


def restore():
    set_core(True, 0)


def st_mask():
    for i in [int(x) for x in args.mask_shapes.split(",")]:
        data = reference.generate_input(**bench_kw(i))
        gs, names = [], []
        for pv8, mode in ((False, 0), (False, 1), (True, 0), (True, 1)):
            set_core(pv8, mode)
            f, ns = core_closure(V7, data)
            gs.append(capture(f))
            names.append(f"{'pv8' if pv8 else 'pv16'}/{'mufu' if mode == 0 else 'MASK'}")
        restore()
        t = [x - FLOOR for x in time_interleaved(gs, args.reps)]
        MASK[i] = t
        say(f"MASK {label(i)} | " + " | ".join(f"{n} {x:7.2f}" for n, x in zip(names, t))
            + f" | exp share: pv16 {100 * (1 - t[1] / t[0]):.1f}%  pv8 {100 * (1 - t[3] / t[2]):.1f}%")
        del gs, data
        torch.cuda.empty_cache()


def st_emu():
    if args.emu == "off":
        return
    if args.emu == "auto":
        if 11 not in MASK:
            say("[lab7] emu: no mask result for shape 11; skipped")
            return
        share = 1 - MASK[11][3] / MASK[11][2]
        if share < 0.15:
            say(f"[lab7] emu: mask saved {100 * share:.1f}% (< 15%) of the FP8-PV core at ver32 full; skipped")
            return
    variants = [tuple(int(x) for x in v.split(":")) for v in args.emu_variants.split(",")]
    best = {}
    for i in [int(x) for x in args.mask_shapes.split(",")]:
        data = reference.generate_input(**bench_kw(i))
        gs = []
        set_core(True, 0)
        f, _ = core_closure(V7, data)
        gs.append(capture(f))
        for fr, rs, dg in variants:
            set_core(True, 2, fr, rs, dg)
            f, _ = core_closure(V7, data)
            gs.append(capture(f))
        restore()
        t = [x - FLOOR for x in time_interleaved(gs, args.reps)]
        say(f"EMU {label(i)} | mufu {t[0]:7.2f} | " + " | ".join(
            f"{fr}:{rs}:d{dg} {x:7.2f} ({100 * (x / t[0] - 1):+.1f}%)" for (fr, rs, dg), x in zip(variants, t[1:])))
        best[i] = min(zip(t[1:], variants))
        del gs, data
        torch.cuda.empty_cache()
    if 11 in best:
        tb, (fr, rs, dg) = best[11]
        set_core(True, 2, fr, rs, dg)
        say(f"[lab7] emu: error checks for {fr}:{rs}:d{dg}")
        ok = V7.k1fa4_self_test(dev)
        say(f"[lab7] v7 emu self-test {'PASS' if ok else 'FAIL'}")
        for i in (11, 9, 10):
            okc, msg = check(lambda d: V7.k1fa4_run(d), i)
            say(f"   emu check {label(i)} {'PASS' if okc else 'FAIL'} {msg[:90]}")
        restore()


def st_err():
    """The problem's check message for the stock (r1) path, for the stock-relative comparison."""
    for i in [int(x) for x in args.err_shapes.split(",")]:
        ok, msg = check(lambda d: V6._k1fa4_r1_path(d), i)
        say(f"ERR {label(i)} r1(stock) {'PASS' if ok else 'FAIL'} {msg[:90]}")


def set_pf(k=False, v=False, vh=False):
    V7.K1FA4_L2PF.update(k=k, v=v, vh=vh)


def st_diag():
    """Timing-only diagnostics of the FP8-PV core: (a) the same bytes through a sequential page table (results
    invalid), (b) L2 prefetch hints in the producer (results valid)."""
    variants = [("base", {}), ("pf_k", {"k": True}), ("pf_v", {"v": True}), ("pf_kv", {"k": True, "v": True}),
                ("vh", {"vh": True}), ("pf_k+vh", {"k": True, "vh": True})]
    for i in [int(x) for x in args.mask_shapes.split(",")]:
        data = reference.generate_input(**bench_kw(i))
        restore()
        set_pf()
        f, ns = core_closure(V7, data)
        g_rand = capture(f)
        pt = data["page_table"]
        nrows = data["k_cache"].shape[0]
        b, mk = pt.shape
        seq_pt = ((torch.arange(b, device=dev)[:, None] * mk + torch.arange(mk, device=dev)[None, :]) % nrows)
        dseq = dict(data)
        dseq["page_table"] = seq_pt.to(torch.int32).contiguous()
        fs, _ = core_closure(V7, dseq)
        g_seq = capture(fs)
        gs = [g_rand, g_seq]
        for nm, kw in variants[1:]:
            set_pf(**kw)
            fv, _ = core_closure(V7, data)
            gs.append(capture(fv))
        set_pf()
        t = [x - FLOOR for x in time_interleaved(gs, args.reps)]
        kvb = 2 * int(data["cache_seqlens"].sum()) * 2 * 64
        say(f"DIAG {label(i)} KV {kvb / 1e6:.0f} MB | random pages {t[0]:7.2f} ({kvb / t[0] / 1e6:.2f} TB/s) | "
            f"sequential pages {t[1]:7.2f} ({kvb / t[1] / 1e6:.2f} TB/s, {100 * (t[1] / t[0] - 1):+.1f}%) | "
            + " | ".join(f"{nm} {x:7.2f} ({100 * (x / t[0] - 1):+.1f}%)" for (nm, _), x in zip(variants[1:], t[2:])))
        del gs, g_rand, g_seq, data, dseq
        torch.cuda.empty_cache()


def st_ncu():
    """Eager core calls for an ncu run (ncu --kernel-name regex:Sm90Fwd): v6 x2, then v7 x2, on --mask-shapes[0]."""
    i = int(args.mask_shapes.split(",")[0])
    data = reference.generate_input(**bench_kw(i))
    for M in (V6, V7):
        f, _ = core_closure(M, data)
        for _ in range(2):
            f()
        torch.cuda.synchronize()
    say(f"[lab7] ncu calls done on {label(i)}")


if args.p8_offset is not None:
    V7.K1FA4_P8_OFFSET = args.p8_offset
say(f"[lab7] v7 K1FA4_P8_OFFSET {V7.K1FA4_P8_OFFSET}")
run_stage("ncu", st_ncu)
run_stage("selftest", st_selftest)
run_stage("err", st_err)
run_stage("diag", st_diag)
run_stage("fn", st_fn)
run_stage("core", st_core)
run_stage("mask", st_mask)
run_stage("emu", st_emu)
say("[lab7] done")
